class Queue:
    def __init__(self):
        self._data = []

    def enqueue(self, item):
        self._data.append(item)

    def dequeue(self):
        if not self._data:
            raise IndexError("dequeue from empty queue")
        return self._data.pop(0)

    def __len__(self):
        return len(self._data)


def test_enqueue_increases_length():
    q = Queue()
    q.enqueue(1)
    assert len(q) == 1
    q.enqueue(2)
    assert len(q) == 2


def test_dequeue_is_fifo():
    q = Queue()
    for i in (1, 2, 3):
        q.enqueue(i)
    assert q.dequeue() == 1
    assert q.dequeue() == 2
    assert q.dequeue() == 3
    assert len(q) == 0


def test_dequeue_empty_raises():
    q = Queue()
    try:
        q.dequeue()
    except IndexError:
        pass
    else:
        raise AssertionError("expected IndexError")


test_enqueue_increases_length()
test_dequeue_is_fifo()
test_dequeue_empty_raises()
print("All tests pass")
